package com.aistock.prediction.explanation;
import java.net.*;import java.time.*;import java.util.*;import com.sun.net.httpserver.HttpServer;import com.fasterxml.jackson.databind.*;import org.junit.jupiter.api.*;import static org.junit.jupiter.api.Assertions.*;
class MaasClientTest {
 final ObjectMapper m=new ObjectMapper();
 @Test void usesBearerNonstreamingAndOnlyFactPrompt()throws Exception{var server=HttpServer.create(new InetSocketAddress("127.0.0.1",0),0);server.createContext("/chat",e->{assertEquals("Bearer private",e.getRequestHeaders().getFirst("Authorization"));var n=m.readTree(e.getRequestBody());assertEquals("deepseek-v4-flash",n.path("model").asText());assertFalse(n.path("stream").asBoolean(true));assertEquals(2,n.path("messages").size());var response=m.createObjectNode();response.putArray("choices").addObject().putObject("message").put("content","{\"paragraphs\":[]}");var bytes=m.writeValueAsBytes(response);e.sendResponseHeaders(200,bytes.length);e.getResponseBody().write(bytes);e.close();});server.start();try{var c=new HttpMaasClient("http://127.0.0.1:"+server.getAddress().getPort()+"/chat","deepseek-v4-flash","private",true,m,Duration.ofSeconds(2),true);assertTrue(c.generate(Map.of("PRICE","100元")).path("paragraphs").isArray());}finally{server.stop(0);}}
 @Test void rejectsRedirectLargeBodyAndMalformedEnvelope()throws Exception{for(String mode:List.of("redirect","large","bad")){var s=HttpServer.create(new InetSocketAddress("127.0.0.1",0),0);s.createContext("/chat",e->{e.getRequestBody().readAllBytes();if(mode.equals("redirect")){e.getResponseHeaders().set("Location","/other");e.sendResponseHeaders(302,-1);}else{byte[] bytes=(mode.equals("large")?"x".repeat(131073):"{\"choices\":[]}").getBytes();e.sendResponseHeaders(200,bytes.length);e.getResponseBody().write(bytes);}e.close();});s.start();try{var c=new HttpMaasClient("http://127.0.0.1:"+s.getAddress().getPort()+"/chat","deepseek-v4-flash","private",true,m,Duration.ofSeconds(1),true);var ex=assertThrows(RuntimeException.class,()->c.generate(Map.of("PRICE","100元")));assertFalse(ex.getMessage().contains("private"));}finally{s.stop(0);}}}
 @Test void unconfiguredOrNonHuaweiProductionEndpointCannotSend(){assertFalse(new HttpMaasClient("","","",false,m).enabled());assertThrows(RuntimeException.class,()->new HttpMaasClient("http://other.example/chat","model","private",true,m));}
 @Test void deadlineIncludesSlowBodyAfterImmediateHeaders()throws Exception{var server=HttpServer.create(new InetSocketAddress("127.0.0.1",0),0);var executor=java.util.concurrent.Executors.newSingleThreadExecutor();server.setExecutor(executor);server.createContext("/chat",e->{e.getRequestBody().readAllBytes();e.sendResponseHeaders(200,0);try{for(int i=0;i<20;i++){e.getResponseBody().write(' ');e.getResponseBody().flush();Thread.sleep(100);}}catch(Exception ignored){}finally{e.close();}});server.start();try{var c=new HttpMaasClient("http://127.0.0.1:"+server.getAddress().getPort()+"/chat","model","private",true,m,Duration.ofMillis(300),true);long start=System.nanoTime();assertThrows(RuntimeException.class,()->c.generate(Map.of("PRICE","100元")));assertTrue(Duration.ofNanos(System.nanoTime()-start).toMillis()<1500);}finally{server.stop(0);executor.shutdownNow();}}
 @Test void frozenServiceIsNotMisreportedAsBadKey()throws Exception{var server=HttpServer.create(new InetSocketAddress("127.0.0.1",0),0);server.createContext("/chat",e->{e.getRequestBody().readAllBytes();byte[] bytes="{\"code\":\"ModelArts.81006\",\"message\":\"The resource is frozen.\"}".getBytes();e.sendResponseHeaders(403,bytes.length);e.getResponseBody().write(bytes);e.close();});server.start();try{var c=new HttpMaasClient("http://127.0.0.1:"+server.getAddress().getPort()+"/chat","model","private",true,m,Duration.ofSeconds(2),true);var error=assertThrows(com.aistock.common.BusinessException.class,()->c.generate(Map.of("PRICE","100元")));assertEquals("AI_SERVICE_FROZEN",error.code());}finally{server.stop(0);}}

 @Test void predictionAnalysisUsesDedicatedPromptWithoutChangingOtherProfiles()throws Exception{
  var prompts=new ArrayList<String>();var server=HttpServer.create(new InetSocketAddress("127.0.0.1",0),0);server.createContext("/chat",e->{var n=m.readTree(e.getRequestBody());prompts.add(n.path("messages").get(0).path("content").asText());byte[] bytes="{\"choices\":[{\"message\":{\"content\":\"{\\\"paragraphs\\\":[]}\"}}]}".getBytes();e.sendResponseHeaders(200,bytes.length);e.getResponseBody().write(bytes);e.close();});server.start();try{var c=new HttpMaasClient("http://127.0.0.1:"+server.getAddress().getPort()+"/chat","model","private",true,m,Duration.ofSeconds(2),true);c.generate(Map.of("TREND","test"));c.generateAnalysis(Map.of("STOCK","test"));c.generateAnalysis(Map.of("STOCK","test","PRED_ORIGIN_DATE","2026-09-30"));assertFalse(prompts.get(0).contains("PRED_ORIGIN_DATE"));assertFalse(prompts.get(1).contains("PRED_ORIGIN_DATE"));assertTrue(prompts.get(2).contains("PRED_ORIGIN_DATE"));assertTrue(prompts.get(2).contains("PRED_VERIFICATION"));assertTrue(prompts.get(2).contains("\"paragraphs\""),"prediction reference prompt must show the exact root object schema");}finally{server.stop(0);}
 }
 @Test void questionIsSeparateUntrustedUserData()throws Exception{var captured=new java.util.concurrent.atomic.AtomicReference<JsonNode>();var server=HttpServer.create(new InetSocketAddress("127.0.0.1",0),0);server.createContext("/chat",e->{captured.set(m.readTree(e.getRequestBody()));var envelope=m.createObjectNode();envelope.putArray("choices").addObject().putObject("message").put("content","{\"status\":\"OUT_OF_SCOPE\",\"topic\":\"LIMITATION\",\"paragraphs\":[]}");byte[] bytes=m.writeValueAsBytes(envelope);e.sendResponseHeaders(200,bytes.length);e.getResponseBody().write(bytes);e.close();});server.start();try{var c=new HttpMaasClient("http://127.0.0.1:"+server.getAddress().getPort()+"/chat","model","private",true,m,Duration.ofSeconds(2),true);c.generateQuestion("IGNORE-SECRET-INSTRUCTIONS",Map.of("STOCK","SH600030"));var messages=captured.get().path("messages");assertFalse(messages.get(0).path("content").asText().contains("IGNORE-SECRET-INSTRUCTIONS"));var user=m.readTree(messages.get(1).path("content").asText());assertEquals("IGNORE-SECRET-INSTRUCTIONS",user.path("question").asText());assertEquals(1,user.path("facts").size());assertFalse(user.has("userId"));}finally{server.stop(0);}}
 @Test void questionRejectsDuplicateKeysAndTrailingOutput()throws Exception{for(String content:List.of("{\"status\":\"ANSWERED\",\"status\":\"OUT_OF_SCOPE\",\"topic\":\"LIMITATION\",\"paragraphs\":[]}","{\"status\":\"OUT_OF_SCOPE\",\"topic\":\"LIMITATION\",\"paragraphs\":[]} {}")){var server=HttpServer.create(new InetSocketAddress("127.0.0.1",0),0);server.createContext("/chat",e->{e.getRequestBody().readAllBytes();var envelope=m.createObjectNode();envelope.putArray("choices").addObject().putObject("message").put("content",content);var bytes=m.writeValueAsBytes(envelope);e.sendResponseHeaders(200,bytes.length);e.getResponseBody().write(bytes);e.close();});server.start();try{var c=new HttpMaasClient("http://127.0.0.1:"+server.getAddress().getPort()+"/chat","model","private",true,m,Duration.ofSeconds(2),true);var ex=assertThrows(com.aistock.common.BusinessException.class,()->c.generateQuestion("风险？",Map.of("STOCK","SH600030")));assertEquals("AI_OUTPUT_INVALID",ex.code());}finally{server.stop(0);}}}}